import{_ as i,W as l,s as o,u as r,I as s,ah as d,w as t,Z as p,A as e}from"./chunks/framework.Dx7wo2et.js";import"./chunks/theme.CjgFg8Ql.js";const C=JSON.parse('{"title":"如何使用 Awk 打印文件中的字段和列 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 Awk 打印文件中的字段和列 | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何使用 Awk 打印文件中的字段和列 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 Awk 打印文件中的字段和列 | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160425 How to Use Awk to Print Fields and Columns in File","title":"如何使用 Awk 打印文件中的字段和列","tag":"201607"},"relativePath":"201607/20160425 How to Use Awk to Print Fields and Columns in File.md","filePath":"[post].md"}'),u={name:"201607/20160425 How to Use Awk to Print Fields and Columns in File.md"};function m(c,n,w,k,g,h){const a=l("Link");return r(),o("div",null,[n[19]||(n[19]=s("h1",{id:"如何使用-awk-打印文件中的字段和列",tabindex:"-1"},[t("如何使用 Awk 打印文件中的字段和列 "),s("a",{class:"header-anchor",href:"#如何使用-awk-打印文件中的字段和列","aria-label":"Permalink to 如何使用 Awk 打印文件中的字段和列"},"​")],-1)),s("p",null,[n[1]||(n[1]=t("在 ")),p(a,{href:"http://www.tecmint.com/tag/awk-command/"},{default:e(()=>n[0]||(n[0]=[t("Linux Awk 命令系列介绍")])),_:1}),n[2]||(n[2]=t(" 的这部分，我们来看一下 awk 最重要的功能之一，字段编辑。"))]),n[20]||(n[20]=s("p",null,"首先我们要知道 Awk 会自动把输入的行切分为字段，字段可以定义为是一些字符集，这些字符集和其它字段被内部字段分隔符分离。",-1)),n[21]||(n[21]=s("p",null,[s("img",{src:"http://www.tecmint.com/wp-content/uploads/2016/04/Awk-Print-Fields-and-Columns.png",alt:""})],-1)),n[22]||(n[22]=s("blockquote",null,[s("p",null,"Awk 输出字段和列")],-1)),s("p",null,[n[4]||(n[4]=t("如果你熟悉 Unix/Linux 或者懂得 ")),p(a,{href:"http://www.tecmint.com/category/bash-shell/"},{default:e(()=>n[3]||(n[3]=[t("bash shell 编程")])),_:1}),n[5]||(n[5]=t("，那么你也应该知道内部字段分隔符（IFS）变量。Awk 默认的 IFS 是 tab 和空格。"))]),n[23]||(n[23]=d(`<p>Awk 字段切分的工作原理如下：当获得一行输入时，根据定义的 IFS，第一个字符集是字段一，用 $1 表示，第二个字符集是字段二，用 $2 表示，第三个字符集是字段三，用 $3 表示，以此类推直到最后一个字符集。</p><p>为了更好的理解 Awk 的字段编辑，让我们来看看下面的例子：</p><p><strong>事例 1:</strong>： 我创建了一个名为 tecmintinfo.txt 的文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># vi tecmintinfo.txt</span></span>
<span class="line"><span># cat tecmintinfo.txt</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Create-File-in-Linux.png" alt=""></p><blockquote><p>在 Linux 中创建文件</p></blockquote><p>然后在命令行中使用以下命令打印 tecmintinfo.txt 文件中的第一、第二和第三个字段。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ awk &#39;//{print $1 $2 $3 }&#39; tecmintinfo.txt</span></span>
<span class="line"><span>TecMint.comisthe</span></span></code></pre></div><p>从上面的输出中你可以看到，三个字段中的第一个是按照定义的 IFS，也就是空格，打印的。</p><ul><li>字段一 “TecMint.com” 使用 $1 访问。</li><li>字段二 “is” 通过 $2 访问。</li><li>字段三 “the” 通过 $3 访问。</li></ul><p>如果你注意打印的输出，可以看到字段值之间并没有分隔开，这是 print 默认的方式。</p><p>为了在字段值之间加入空格，你需要像下面这样添加（,）分隔符：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ awk &#39;//{print $1, $2, $3; }&#39; tecmintinfo.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TecMint.com is the</span></span></code></pre></div><p>很重要而且必须牢记的一点是，Awk 中 （$） 的使用和在 shell 脚本中不一样。</p><p>在 shell 脚本中 （$） 用于获取变量的值，而在 Awk 中 （$） 只用于获取一个字段的内容，而不能用于获取变量的值。</p><p><strong>事例2</strong>： 让我们再看一个使用多行文件 my_shoping.list 的例子。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>No	Item_Name		Unit_Price	Quantity	Price</span></span>
<span class="line"><span>1	Mouse			#20,000		   1		#20,000</span></span>
<span class="line"><span>2 	Monitor			#500,000	   1		#500,000</span></span>
<span class="line"><span>3	RAM_Chips		#150,000	   2		#300,000</span></span>
<span class="line"><span>4	Ethernet_Cables	        #30,000		   4		#120,000</span></span></code></pre></div><p>假设你只想打印购物清单中每个物品的 Unit_Price，你需要允许下面的命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ awk &#39;//{print $2, $3 }&#39; my_shopping.txt </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Item_Name Unit_Price</span></span>
<span class="line"><span>Mouse #20,000</span></span>
<span class="line"><span>Monitor #500,000</span></span>
<span class="line"><span>RAM_Chips #150,000</span></span>
<span class="line"><span>Ethernet_Cables #30,000</span></span></code></pre></div><p>Awk 也有一个 printf 命令，它能帮助你用更好的方式格式化输出，正如你可以看到上面的输出并不清晰。</p><p>使用 printf 格式化输出 Item_Name 和 Unit_Price：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ awk &#39;//{printf &quot;%-10s %s\\n&quot;,$2, $3 }&#39; my_shopping.txt </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Item_Name  Unit_Price</span></span>
<span class="line"><span>Mouse      #20,000</span></span>
<span class="line"><span>Monitor    #500,000</span></span>
<span class="line"><span>RAM_Chips  #150,000</span></span>
<span class="line"><span>Ethernet_Cables #30,000</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to 总结">​</a></h3><p>使用 Awk 进行文本和字符串过滤时字段编辑功能非常重要，它能帮助你从列表中获取列的特定数据。同时需要记住 Awk 中 （$） 操作符和 shell 脚本中不一样。</p><p>我希望这篇文章能对你有所帮助，如果你需要获取其它信息或者有任何疑问，都可以在下面的评论框中告诉我们。</p><hr>`,26)),s("p",null,[n[7]||(n[7]=t("via: ")),p(a,{href:"http://www.tecmint.com/awk-print-fields-columns-with-space-separator/?utm_source=feedburner&utm_medium=feed&utm_campaign=Feed%3A+tecmint+%28Tecmint%3A+Linux+Howto%27s+Guide%29"},{default:e(()=>n[6]||(n[6]=[t("http://www.tecmint.com/awk-print-fields-columns-with-space-separator/?utm_source=feedburner&utm_medium=feed&utm_campaign=Feed%3A+tecmint+(Tecmint%3A+Linux+Howto's+Guide)")])),_:1})]),s("p",null,[n[11]||(n[11]=t("作者：")),p(a,{href:"http://www.tecmint.com/author/aaronkili/"},{default:e(()=>n[8]||(n[8]=[t("Aaron Kili")])),_:1}),n[12]||(n[12]=t(" 译者：")),p(a,{href:"https://github.com/ictlyh"},{default:e(()=>n[9]||(n[9]=[t("ictlyh")])),_:1}),n[13]||(n[13]=t(" 校对：")),p(a,{href:"https://github.com/%E6%A0%A1%E5%AF%B9%E8%80%85ID"},{default:e(()=>n[10]||(n[10]=[t("校对者ID")])),_:1})]),s("p",null,[n[16]||(n[16]=t("本文由 ")),p(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>n[14]||(n[14]=[t("LCTT")])),_:1}),n[17]||(n[17]=t(" 原创编译，")),p(a,{href:"https://linux.cn/"},{default:e(()=>n[15]||(n[15]=[t("Linux中国")])),_:1}),n[18]||(n[18]=t(" 荣誉推出"))])])}const A=i(u,[["render",m]]);export{C as __pageData,A as default};
